export const ui = {
  route: "resumen",
  filters: { status: "all", supplier: "", q: "", direction: "all" },
  supplierQuery: "",
  jobs: [],
  // Pantalla de ventas: periodo elegido y fechas a mano.
  sales: { range: "year", from: "", to: "" },
};

const ROUTES = ["resumen", "ventas", "compras", "proveedores", "correo", "importar"];


/* ------------------------------------------------------------------ */
/* Utilidades de pintado                                              */
/* ------------------------------------------------------------------ */

function statusPill(inv, interactive = true) {
  const paid = inv.status === STATUS.PAID;
  const cls = paid ? "paid" : "pending";
  const label = paid ? "Pagado" : "Pendiente";
  if (!interactive) return `<span class="status static ${cls}">${label}</span>`;
  return `<button class="status ${cls}" data-action="toggle-status" data-id="${inv.id}"
    title="Cambiar a ${paid ? "pendiente" : "pagado"}">${label}</button>`;
}

function supplierName(id) {
  const s = supplierById(id);
  return s ? s.name : "Sin proveedor";
}
